select
  id, circle_id, content, pic_urls, reply_count, created_by, created_time, updated_by, updated_time, is_deleted
from share_moment


        and id = #{id}


        and circle_id = #{circleId}


        and content = #{content}


        and pic_urls = #{picUrls}


        and reply_count = #{replyCount}


        and created_by = #{createdBy}


        and created_time = #{createdTime}


        and updated_by = #{updatedBy}


        and updated_time = #{updatedTime}


        and is_deleted = #{isDeleted}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from share_moment


        and id = #{id}


        and circle_id = #{circleId}


        and content = #{content}


        and pic_urls = #{picUrls}


